import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"TUI-Explorer","description":"","frontmatter":{},"headers":[],"relativePath":"de/advanced/tui.md","filePath":"de/advanced/tui.md","lastUpdated":1784903584000}'),r={name:"de/advanced/tui.md"};function d(s,e,l,o,u,c){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="tui-explorer" tabindex="-1">TUI-Explorer <a class="header-anchor" href="#tui-explorer" aria-label="Permalink to &quot;TUI-Explorer&quot;">​</a></h1><h2 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h2><p>swag2mcp enthält eine integrierte TUI (Terminal User Interface) für die interaktive API-Erkundung. Es ist eine Vollbild-Terminalanwendung, mit der Sie API-Endpunkte durchsuchen, inspizieren und aufrufen können, ohne das Terminal zu verlassen.</p><h2 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to &quot;Start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>Wenn keine Konfigurationsdatei existiert, startet die TUI automatisch zuerst den Initialisierungsassistenten.</p><h2 id="modi" tabindex="-1">Modi <a class="header-anchor" href="#modi" aria-label="Permalink to &quot;Modi&quot;">​</a></h2><p>Die TUI hat drei Modi, die mit der <code>Tab</code>-Taste umgeschaltet werden können:</p><h3 id="suchmodus" tabindex="-1">Suchmodus <a class="header-anchor" href="#suchmodus" aria-label="Permalink to &quot;Suchmodus&quot;">​</a></h3><p>Volltextsuche über alle Endpunkte aller Specs. Unterstützt dieselbe Abfragesyntax wie das <code>search</code>-MCP-Tool.</p><ul><li>Geben Sie eine Abfrage ein, um nach Endpunktnamen, Pfaden und Beschreibungen zu suchen</li><li>Filtern Sie Ergebnisse nach Methode, Tag oder Pfad</li><li>Zeigen Sie Endpunktdetails mit einem Tastendruck an</li><li>Navigieren Sie durch Ergebnisse mit Seitenumbrüchen (10 Elemente pro Seite)</li></ul><h3 id="durchsuchen-modus" tabindex="-1">Durchsuchen-Modus <a class="header-anchor" href="#durchsuchen-modus" aria-label="Permalink to &quot;Durchsuchen-Modus&quot;">​</a></h3><p>Baumnavigation durch die Spec-Hierarchie:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Endpunkt</span></span></code></pre></div><ul><li>Navigieren Sie im Baum nach unten, um bestimmte Endpunkte zu finden</li><li>Zeigen Sie Endpunktdetails an (Parameter, Anforderungstext, Antworten)</li><li>Rufen Sie die API direkt aus der TUI auf</li><li>Speichern Sie Endpunktdetails als JSON-Datei</li></ul><h3 id="auth-modus" tabindex="-1">Auth-Modus <a class="header-anchor" href="#auth-modus" aria-label="Permalink to &quot;Auth-Modus&quot;">​</a></h3><p>Zeigen Sie Authentifizierungstokens und Header für jede Spec an. Nützlich zum Debuggen oder Generieren von curl-Befehlen.</p><h2 id="steuerung" tabindex="-1">Steuerung <a class="header-anchor" href="#steuerung" aria-label="Permalink to &quot;Steuerung&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Taste</th><th>Aktion</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Nach oben/unten navigieren</td></tr><tr><td><code>Enter</code></td><td>Auswählen oder öffnen</td></tr><tr><td><code>Esc</code></td><td>Eine Ebene zurück</td></tr><tr><td><code>Tab</code></td><td>Zwischen Such-, Durchsuchen- und Auth-Modus wechseln</td></tr><tr><td><code>/</code></td><td>Sucheingabe fokussieren</td></tr><tr><td><code>N</code> / <code>P</code></td><td>Nächste / vorherige Seite</td></tr><tr><td><code>B</code></td><td>Zurück zum vorherigen Bildschirm</td></tr><tr><td><code>M</code></td><td>Zurück zum Hauptmenü</td></tr><tr><td><code>S</code></td><td>Endpunktdetail als JSON-Datei speichern</td></tr><tr><td><code>q</code> / <code>Ctrl+C</code></td><td>Beenden</td></tr></tbody></table><h2 id="zustande" tabindex="-1">Zustände <a class="header-anchor" href="#zustande" aria-label="Permalink to &quot;Zustände&quot;">​</a></h2><p>Die TUI durchläuft diese Zustände während der Navigation:</p><ol><li><strong>Laden</strong> — Daten aus dem Arbeitsbereich laden</li><li><strong>Suche</strong> — Suchmodus mit Abfrageeingabe</li><li><strong>Durchsuchen</strong> — Durchsuchen-Modus mit Spec-Liste</li><li><strong>Spec-Liste</strong> — Liste aller Specs</li><li><strong>Collection-Liste</strong> — Collections innerhalb einer Spec</li><li><strong>Tag-Liste</strong> — Tags innerhalb einer Collection</li><li><strong>Endpunkt-Liste</strong> — Endpunkte innerhalb eines Tags</li><li><strong>Endpunkt-Detail</strong> — vollständige Endpunktinformationen</li><li><strong>Aufruf-Ergebnis</strong> — Ergebnis des API-Aufrufs</li><li><strong>Fehler</strong> — Fehlerzustand mit Meldung</li></ol><h2 id="endpunkt-detailansicht" tabindex="-1">Endpunkt-Detailansicht <a class="header-anchor" href="#endpunkt-detailansicht" aria-label="Permalink to &quot;Endpunkt-Detailansicht&quot;">​</a></h2><p>Wenn Sie einen Endpunkt auswählen, zeigt die TUI:</p><ul><li>HTTP-Methode und Pfad</li><li>Basis-URL und vollständige URL</li><li>Zusammenfassung und Beschreibung</li><li>Alle Parameter (Name, Ort, Typ, erforderlich)</li><li>Anforderungstext-Schema (falls zutreffend)</li><li>Antwortcodes und Schemata</li><li>Veraltungsstatus</li></ul><h2 id="anforderungen" tabindex="-1">Anforderungen <a class="header-anchor" href="#anforderungen" aria-label="Permalink to &quot;Anforderungen&quot;">​</a></h2><ul><li><strong>Terminalgröße:</strong> Mindestens 80×24 Zeichen</li><li><strong>Terminalemulator:</strong> Funktioniert in den meisten modernen Terminals (iTerm2, Terminal.app, GNOME Terminal, Windows Terminal usw.)</li><li><strong>SSH:</strong> Funktioniert über SSH-Verbindungen</li></ul><h2 id="wichtige-hinweise" tabindex="-1">Wichtige Hinweise <a class="header-anchor" href="#wichtige-hinweise" aria-label="Permalink to &quot;Wichtige Hinweise&quot;">​</a></h2><ul><li><strong>Auto-Init</strong> — wenn keine Konfigurationsdatei existiert, startet die TUI automatisch den Initialisierungsassistenten</li><li><strong>Seitenumbrüche</strong> — Listen werden mit 10 Elementen pro Seite umgebrochen. Verwenden Sie <code>N</code> und <code>P</code> zum Navigieren</li><li><strong>Endpunktdetails speichern</strong> — drücken Sie <code>S</code> in der Endpunkt-Detailansicht, um das vollständige Detail als JSON-Datei im aktuellen Verzeichnis zu speichern</li><li><strong>Auth-Modus</strong> — zeigt Tokens und Header zum Debuggen an. In der Produktion kann das Auth-Tool mit <code>--disable-llm-auth</code> deaktiviert werden</li></ul>',29)])])}const p=t(r,[["render",d]]);export{g as __pageData,p as default};
